"""Self-test for tools/inspect_nvpresent.py against synthetic data (no NVIDIA files).

    python tests/test_inspect.py
"""
import struct
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
import inspect_nvpresent as nvp  # noqa: E402

PTX = """//
// Generated by NVIDIA NVVM Compiler
//
.version 8.5
.target sm_89
.address_size 64

.visible .entry Kernel_Blend(
\t.param .align 8 .b8 Kernel_Blend_param_0[144],
\t.param .u64 Kernel_Blend_param_1
)
{
\t.reg .f32 \t%f<8>;
\tld.param.f32 \t%f1, [Kernel_Blend_param_0+32];
\tld.param.u64 \t%rd1, [Kernel_Blend_param_1];
$L__BB0_3:
\tmul.ftz.f32 \t%f2, %f1, 0f3F000000;
\tmul.ftz.f32 \t%f3, %f2, 0f3F000000;
\tadd.ftz.f32 \t%f4, %f3, 0f3F000000;
\tret;
}

.visible .entry Kernel_Flow(
\t.param .u64 Kernel_Flow_param_0
)
{
\tld.param.u64 \t%rd1, [Kernel_Flow_param_0];
\tret;
}
"""


def lz4_literals_only(raw: bytes) -> bytes:
    n = len(raw)
    if n < 15:
        return bytes([n << 4]) + raw
    out, rest = bytearray([0xF0]), n - 15
    while rest >= 255:
        out.append(255)
        rest -= 255
    out.append(rest)
    return bytes(out) + raw


def entry(kind, arch, payload, compressed=0, raw_size=0, flags=0x11):
    hdr = struct.pack("<HHIQIIHHIIIQQQ", kind, 0x0101, 64, len(payload), compressed, 0,
                      5, 8, arch, 0, 0, flags, 0, raw_size)
    assert len(hdr) == 64
    return hdr + payload


def minimal_cubin(kernel: str) -> bytes:
    names = [b"", b".shstrtab", b".text." + kernel.encode(), b".nv.constant0." + kernel.encode()]
    strtab, offsets = b"", []
    for n in names:
        offsets.append(len(strtab))
        strtab += n + b"\0"
    body = b"\x90" * 96
    shoff = 0x40 + len(strtab) + len(body)

    def sh(name, offset, size):
        return struct.pack("<IIQQQQIIQQ", name, 1, 0, 0, offset, size, 0, 0, 1, 0)

    sections = sh(0, 0, 0) + sh(offsets[1], 0x40, len(strtab)) + \
        sh(offsets[2], 0x40 + len(strtab), 64) + sh(offsets[3], 0x40 + len(strtab) + 64, 32)
    header = b"\x7fELF\x02\x01\x01" + b"\0" * 9 + struct.pack(
        "<HHIQQQIHHHHHH", 2, 190, 1, 0, 0, shoff, 0x06005904, 0x40, 0, 0, 0x40, 4, 1)
    assert len(header) == 0x40
    return header + strtab + body + sections


def build_fatbin() -> bytes:
    raw = PTX.encode()
    packed = lz4_literals_only(raw)
    pad = (-len(packed)) % 8
    body = entry(1, 89, packed + b"\0" * pad, compressed=len(packed), raw_size=len(raw), flags=0x2011)
    body += entry(2, 89, minimal_cubin("Kernel_Blend"))
    body += entry(2, 120, minimal_cubin("Kernel_Blend"))
    return struct.pack("<IHHQ", 0xBA55ED50, 1, 16, len(body)) + body


def main():
    # LZ4 with a real back-reference, including an overlapping one.
    assert nvp.lz4_block_decompress(b"\x44abcd\x04\x00\x10z", 13) == b"abcdabcdabcdz"
    assert nvp.lz4_block_decompress(b"\x1fa\x01\x00\x05\x10b", 26) == b"a" * 25 + b"b"

    fat = build_fatbin()
    blob = b"\x00" * 37 + b"cuModuleLoadData\0NVPRESENT_LOG_LEVEL\0" + fat + b"\x50\xed\x55\xba" + b"\x00" * 64
    found = nvp.find_fatbins(blob)
    assert len(found) == 1 and found[0]["size"] == len(fat), found
    entries = found[0]["entries"]
    assert [(e["kind"], e["arch"]) for e in entries] == [(1, 89), (2, 89), (2, 120)]

    kernels = nvp.analyze_ptx(nvp.entry_bytes(blob, entries[0]).decode())
    blend, flow = kernels
    assert blend["name"] == "Kernel_Blend" and flow["name"] == "Kernel_Flow"
    assert blend["params"][0] == ("Kernel_Blend_param_0", "b8", 144)
    assert blend["midpoint_mul"] == 2 and blend["half_constants"] == 3
    assert blend["float_loads"] == [("Kernel_Blend_param_0", 32)]
    assert flow["midpoint_mul"] == 0 and flow["float_loads"] == []

    cubin = nvp.analyze_cubin(nvp.entry_bytes(blob, entries[1]))
    assert cubin["kernels"] == {"Kernel_Blend": {"text": 64, "const0": 32}}, cubin

    with tempfile.TemporaryDirectory() as tmp:
        path = Path(tmp) / "blob.bin"
        path.write_bytes(blob)
        out = subprocess.run([sys.executable, str(ROOT / "tools" / "inspect_nvpresent.py"), str(path),
                              "--dump", str(Path(tmp) / "k")], capture_output=True, text=True)
        assert out.returncode == 0, out.stderr
        assert "Kernel_Blend: 2 midpoint multiplies, 1 f32 parameter loads" in out.stdout, out.stdout
        assert (Path(tmp) / "k" / "fatbin00_sm89.ptx").read_text(encoding="latin-1") == PTX
        assert "NVPRESENT_LOG_LEVEL" in out.stdout

    # PE parsing, when a 64-bit PE is supplied (any DLL/EXE will do).
    for arg in sys.argv[1:]:
        pe = nvp.PE(Path(arg).read_bytes())
        print(arg, "sections", [s["name"] for s in pe.sections], "exports", len(pe.exports()),
              "imports", {k: len(v) for k, v in pe.imports().items()})
    print("ok")


if __name__ == "__main__":
    main()
